{
  "schemaVersion": "0.2",
  "slug": "form",
  "name": "Form",
  "status": "experimental",
  "purpose": "Groups input fields and submits them with a consistent action area.",
  "scenarios": [
    "Submit a sign-in form",
    "Collect feedback with a submit button",
    "Compose fields inside a dialog"
  ],
  "props": {
    "onSubmit": {
      "type": "event",
      "required": true,
      "description": "Receives the native submit event.",
      "payload": "(event: React.FormEvent<HTMLFormElement>) => void"
    },
    "submitLabel": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the submit action."
    },
    "children": {
      "type": "node",
      "required": true,
      "description": "Form fields and related controls."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Form is ready to submit."
    }
  ],
  "composition": {
    "allowedParents": [
      "dialog",
      "page",
      "app-shell"
    ],
    "allowedChildren": [
      "input",
      "textarea",
      "select",
      "checkbox",
      "radio",
      "switch",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use the form only for layout; use Stack for that.",
    "Do not suppress the submit event without providing an alternative submit control."
  ],
  "a11y": {
    "role": "form",
    "keyboard": [
      "Tab moves between fields",
      "Enter submits from a native input"
    ],
    "focus": "Focus follows the document order through fields and the submit button.",
    "labeling": "Form fields provide their own labels; the submit button is labelled by submitLabel.",
    "wcag": [
      "1.3.1",
      "2.1.1",
      "3.3.2"
    ]
  },
  "responsive": {
    "strategy": "Fields and actions stack vertically; on wider screens the action area aligns to the start.",
    "breakpoints": {
      "compact": "Fields and submit button use the full inline size.",
      "medium": "Fields keep their natural width; actions align to the start.",
      "large": "Fields keep their natural width; actions align to the start."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. The action area aligns to the inline start.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "form",
    "states": [
      "default"
    ],
    "intents": [
      "submit-data"
    ]
  },
  "mechanics": "Form groups fields and a submit action. onSubmit receives the native submit event; preventDefault in SPA handlers. submitLabel names the submit button. Children are the fields. The action area stacks on compact and aligns to inline-start on wider containers.",
  "usage": [
    "Import Form and field components from @chameleon-ui/components.",
    "Pass submitLabel and onSubmit. Put Input, Select, and similar controls in children.",
    "Let the Form submit button remain; do not hide it without another submit control."
  ],
  "exports": [
    {
      "name": "Form",
      "kind": "component",
      "signature": "function Form(props: FormProps): JSX.Element",
      "description": "Field group with onSubmit and a labelled submit action."
    },
    {
      "name": "FormProps",
      "kind": "type",
      "signature": "interface FormProps",
      "description": "onSubmit, submitLabel, and children."
    }
  ]
}

import { Button } from '../button/Button.js'
import type { FormEvent, ReactNode } from 'react'
import './styles.css'

export interface FormProps {
  onSubmit: (event: FormEvent<HTMLFormElement>) => void
  submitLabel: string
  /** Accessible name for the form landmark. Defaults to submitLabel context. */
  label?: string
  children: ReactNode
  className?: string
}

export function Form({ onSubmit, submitLabel, label, children, className }: FormProps) {
  const classes = ['cu-form', className].filter(Boolean).join(' ')

  return (
    <form
      className={classes}
      aria-label={label ?? submitLabel}
      data-ai-role="form"
      data-ai-intent="submit-data"
      data-ai-state="default"
      onSubmit={onSubmit}
    >
      {children}
      <div className="cu-form__actions">
        <Button type="submit">{submitLabel}</Button>
      </div>
    </form>
  )
}

.cu-form {
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-3);
}

.cu-form__actions {
  display: flex;
  justify-content: flex-start;
  margin-block-start: var(--cu-space-2);
}
